create table `notification_preferences` (`id` bigint unsigned not null auto_increment primary key, `user_id` bigint unsigned not null, `notification_template_id` bigint unsigned not null, `mail_enabled` tinyint(1) not null default '1', `in_app_enabled` tinyint(1) not null default '1', `created_at` timestamp null, `updated_at` timestamp null) default character set {{charset}} collate {{collation}};
alter table `notification_preferences` add constraint `notification_preferences_user_id_foreign` foreign key (`user_id`) references `users` (`id`) on delete cascade;
alter table `notification_preferences` add constraint `notification_preferences_notification_template_id_foreign` foreign key (`notification_template_id`) references `notification_templates` (`id`) on delete cascade;
